using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using ProjectAPI.Domain.Identity.Entities;
namespace ProjectAPI.Infrastructure.Configurations;
public sealed class RolePermissionConfiguration : IEntityTypeConfiguration<RolePermission> { public void Configure(EntityTypeBuilder<RolePermission> b) { b.ToTable("RolePermissions"); b.HasKey(x=>x.Id); b.Property(x=>x.RoleCode).HasMaxLength(80).IsRequired(); b.Property(x=>x.Resource).HasMaxLength(80).IsRequired(); b.Property(x=>x.Action).HasMaxLength(40).IsRequired(); b.HasIndex(x=>new{x.RoleCode,x.Resource,x.Action}).IsUnique(); } }
public sealed class UserPermissionOverrideConfiguration : IEntityTypeConfiguration<UserPermissionOverride> { public void Configure(EntityTypeBuilder<UserPermissionOverride> b) { b.ToTable("UserPermissionOverrides"); b.HasKey(x=>x.Id); b.Property(x=>x.UserId).HasMaxLength(450).IsRequired(); b.Property(x=>x.Resource).HasMaxLength(80).IsRequired(); b.Property(x=>x.Action).HasMaxLength(40).IsRequired(); b.HasIndex(x=>new{x.UserId,x.Resource,x.Action}).IsUnique(); } }
public sealed class PermissionEndpointConfiguration : IEntityTypeConfiguration<PermissionEndpoint> { public void Configure(EntityTypeBuilder<PermissionEndpoint> b) { b.ToTable("PermissionEndpoints"); b.HasKey(x=>x.Id); b.Property(x=>x.Key).HasMaxLength(180).IsRequired(); b.Property(x=>x.Module).HasMaxLength(100).IsRequired(); b.Property(x=>x.Controller).HasMaxLength(100).IsRequired(); b.Property(x=>x.ActionName).HasMaxLength(120).IsRequired(); b.Property(x=>x.HttpMethod).HasMaxLength(12).IsRequired(); b.Property(x=>x.RouteTemplate).HasMaxLength(300).IsRequired(); b.HasIndex(x=>x.Key).IsUnique(); } }
